// Cada obra tiene una descripción propia. Para añadir un fondo, guarda la imagen en assets/ y agrega un objeto.
window.GALLERY_SCENES = [
  {id:"ahri-jonia",name:"Ahri",title:"El susurro de Jonia",region:"JONIA · NOCHE",description:"En un jardín de Jonia, Ahri percibe recuerdos entre los pétalos y el agua. Su magia ilumina la noche con una belleza serena que esconde una historia mucho más antigua.",file:"01-ahri-jonia.png",alt:"Ahri en un jardín nocturno de Jonia"},
  {id:"yasuo-amanecer",name:"Yasuo",title:"El camino del viento",region:"JONIA · AMANECER",description:"Yasuo se detiene ante el valle al amanecer. El viento mueve la hierba a su alrededor mientras el espadachín errante busca un momento de calma antes de seguir su camino.",file:"02-yasuo-amanecer.png",alt:"Yasuo en un valle de bambú al amanecer"},
  {id:"yasuo-filo-ceniza",name:"Yasuo",title:"Filo de ceniza",region:"JONIA · NOCHE",description:"Sobre una cresta envuelta en bruma, Yasuo sostiene una hoja encendida por las brasas. La luna recorta su silueta y convierte este instante de silencio en el preludio de otro viaje.",file:"15-yasuo-filo-de-ceniza.png",alt:"Yasuo con armadura oscura y espada de brasa sobre una cresta nocturna"},
  {id:"aatrox-eclipse",name:"Aatrox",title:"Eclipse de sangre",region:"RUNATERRA · ECLIPSE",description:"Bajo un eclipse rojo, Aatrox se alza sobre el campo de batalla con su espada oscura. La escena captura la escala devastadora de un guerrero que parece desafiar al propio cielo.",file:"16-aatrox-eclipse.webp",alt:"Aatrox con alas y espada sobre un campo de batalla bajo un eclipse"},
  {id:"akali-lluvia",name:"Akali",title:"Lluvia sobre Jonia",region:"JONIA · CREPÚSCULO",description:"La lluvia resbala por los tejados de Jonia mientras Akali observa el valle. Oculta entre sombras, la asesina está lista para moverse antes de que alguien advierta su presencia.",file:"17-akali-lluvia.webp",alt:"Akali con kama sobre un tejado lluvioso de Jonia"},
  {id:"akshan-shurima",name:"Akshan",title:"Sol de Shurima",region:"SHURIMA · ATARDECER",description:"Desde una azotea de Shurima, Akshan domina las calles bañadas por el sol. Su arma y su gancho prometen una entrada tan temeraria como precisa entre las cúpulas doradas.",file:"18-akshan-shurima.webp",alt:"Akshan en una azotea de Shurima al atardecer"},
  {id:"alistar-arena",name:"Alistar",title:"Después de la arena",region:"NOXUS · ATARDECER",description:"El polvo se asienta en una arena de Noxus y Alistar sigue en pie. La luz del atardecer revela la fuerza y la dignidad de quien se niega a volver a vivir encadenado.",file:"19-alistar-arena.webp",alt:"Alistar en una arena de piedra bajo la luz del atardecer"},
  {id:"ambessa-noxus",name:"Ambessa",title:"Voluntad de hierro",region:"NOXUS · OCASO",description:"Ambessa contempla una fortaleza noxiana antes de la batalla. Sus armas descansan por un momento, aunque cada gesto deja ver la disciplina y la ambición de una estratega implacable.",file:"20-ambessa-noxus.webp",alt:"Ambessa con armas de cadena frente a una fortaleza noxiana"},
  {id:"amumu-luna",name:"Amumu",title:"La luna y el pequeño",region:"SHURIMA · NOCHE",description:"Junto a un estanque en ruinas, Amumu mira el reflejo de la luna. El desierto guarda silencio alrededor del pequeño viajero, cuya mayor aventura sigue siendo encontrar compañía.",file:"21-amumu-luna.webp",alt:"Amumu sentado junto a un estanque de ruinas shurimanas"},
  {id:"anivia-aurora",name:"Anivia",title:"Alas de invierno",region:"FRELJORD · AURORA",description:"Anivia abre sus alas de hielo bajo la aurora de Freljord. El resplandor cruza las montañas y anuncia que el espíritu del invierno vuelve a proteger estas tierras.",file:"22-anivia-aurora.webp",alt:"Anivia, fénix de hielo, bajo la aurora de Freljord"},
  {id:"annie-tibbers",name:"Annie",title:"Un secreto en el bosque",region:"RUNATERRA · CREPÚSCULO",description:"Annie y Tibbers descubren una luz entre los árboles al anochecer. Parece una escena inocente, hasta que el brillo cálido a su alrededor insinúa lo poderosa que puede ser su magia.",file:"23-annie-tibbers.webp",alt:"Annie con Tibbers y una llama pequeña en un bosque al atardecer"},
  {id:"aphelios-luna",name:"Aphelios",title:"Vigilia lunar",region:"TARGON · NOCHE",description:"Aphelios permanece en vigilia bajo el cielo de Targon. La luz de la luna perfila sus armas y recuerda el vínculo silencioso que mantiene con Alune más allá de lo visible.",file:"24-aphelios-luna.webp",alt:"Aphelios con arma lunar en un acantilado de Targon"},
  {id:"aurora-espiritus",name:"Aurora",title:"Entre dos mundos",region:"FRELJORD · ALBA",description:"En la nieve de Freljord, Aurora observa a los espíritus cruzar el paisaje. Para ella, la frontera entre ambos mundos es una invitación a descubrir aquello que otros no pueden ver.",file:"25-aurora-espiritus.webp",alt:"Aurora entre nieve y luces espirituales en Freljord"},
  {id:"azir-shurima",name:"Azir",title:"El trono del desierto",region:"SHURIMA · AMANECER",description:"Desde una terraza dorada, Azir contempla el desierto al amanecer. Las ruinas y el sol naciente convierten la escena en una promesa de renacimiento para Shurima.",file:"26-azir-shurima.webp",alt:"Azir con armadura dorada ante el desierto de Shurima"},
  {id:"bardo-portal",name:"Bardo",title:"El sendero secreto",region:"RUNATERRA · NOCHE",description:"Bardo avanza por un sendero nocturno acompañado de pequeñas luces. Su presencia transforma el bosque en un lugar extraño y tranquilo, como si el universo guardara allí un secreto.",file:"27-bardo-portal.webp",alt:"Bardo y sus meeps junto a un portal en un bosque nocturno"},
  {id:"belveth-vacio",name:"Bel'Veth",title:"Marea del Vacío",region:"EL VACÍO · NOCHE",description:"Bel'Veth emerge sobre un mar de ruinas violetas. La oscuridad del Vacío se extiende a su alrededor, mientras su figura anuncia un futuro creado a su propia imagen.",file:"28-belveth-vacio.webp",alt:"Bel'Veth con alas violetas sobre un paisaje del Vacío"},
  {id:"blitzcrank-zaun",name:"Blitzcrank",title:"Corazón de vapor",region:"ZAUN · NOCHE",description:"Entre vapor y lluvia, Blitzcrank recorre una pasarela de Zaun. Bajo su enorme armazón metálico late la idea de que incluso una máquina puede escoger ayudar a otros.",file:"29-blitzcrank-zaun.webp",alt:"Blitzcrank sobre un puente de fábrica en Zaun"},
  {id:"brand-fuego",name:"Brand",title:"Llama indomable",region:"RUNATERRA · NOCHE",description:"Brand enciende con sus llamas un camino de piedra abandonado. El fuego rompe la oscuridad, pero también revela lo difícil que resulta contener una fuerza que solo quiere propagarse.",file:"30-brand-fuego.webp",alt:"Brand envuelto en llamas en unas ruinas nocturnas"},
  {id:"braum-freljord",name:"Braum",title:"El corazón del norte",region:"FRELJORD · AMANECER",description:"Braum sostiene su escudo ante un paso nevado de Freljord. Detrás de su sonrisa hay una promesa sencilla: nadie cruzará el frío en soledad mientras él pueda ayudar.",file:"31-braum-freljord.webp",alt:"Braum con escudo bajo la aurora de Freljord"},
  {id:"briar-noxus",name:"Briar",title:"Rosas de medianoche",region:"NOXUS · NOCHE",description:"Entre cadenas y rosas oscuras, Briar aguarda en una fortaleza noxiana. Su quietud dura apenas un instante; la energía imprevisible de la joven amenaza con desbordar cualquier muro.",file:"32-briar-noxus.webp",alt:"Briar entre rosas rojas en un patio noxiano"},
  {id:"caitlyn-piltover",name:"Caitlyn",title:"Guardia del horizonte",region:"PILTOVER · ATARDECER",description:"Caitlyn vigila Piltover desde un balcón al atardecer. Su mirada sigue las calles con la paciencia de una investigadora que sabe encontrar una pista incluso entre miles de luces.",file:"33-caitlyn-piltover.webp",alt:"Caitlyn con rifle frente a Piltover al atardecer"},
  {id:"camille-piltover",name:"Camille",title:"Precisión nocturna",region:"PILTOVER · NOCHE",description:"La noche cubre Piltover mientras Camille calcula su siguiente movimiento. Bajo el brillo elegante de la ciudad se esconde una guardiana capaz de actuar con una precisión inquietante.",file:"34-camille-piltover.webp",alt:"Camille con piernas de acero en un balcón nocturno"},
  {id:"cassiopeia-templo",name:"Cassiopeia",title:"El templo esmeralda",region:"SHURIMA · CREPÚSCULO",description:"Cassiopeia reposa entre las columnas de un templo shurimano. La piedra antigua y la luz esmeralda rodean a una figura tan seductora como peligrosa, nacida de secretos que debieron permanecer enterrados.",file:"35-cassiopeia-templo.webp",alt:"Cassiopeia con cuerpo de serpiente en un templo de Shurima"},
  {id:"jinx-zaun",name:"Jinx",title:"Luces de Zaun",region:"ZAUN · NOCHE",description:"Desde lo alto de Zaun, Jinx observa una ciudad encendida por el neón. Los colores parecen vibrar con su imaginación, siempre a un paso de convertir la noche en un espectáculo impredecible.",file:"03-jinx-zaun.png",alt:"Jinx en un tejado sobre la ciudad nocturna"},
  {id:"aurelion-sol",name:"Aurelion Sol",title:"El cosmos despierta",region:"COSMOS · CREPÚSCULO",description:"Aurelion Sol atraviesa nebulosas y estrellas que parecen responder a su paso. Ante el forjador de mundos, el horizonte terrestre desaparece y la pantalla se abre a una escala cósmica.",file:"04-aurelion-sol-cosmos.png",alt:"Aurelion Sol en un cielo cósmico"},
  {id:"lux-demacia",name:"Lux",title:"Luz sobre Demacia",region:"DEMACIA · AMANECER",description:"La primera luz baña las torres de Demacia mientras Lux deja escapar un destello de magia. La escena muestra la esperanza de alguien que aprende a brillar sin esconderse.",file:"05-lux-demacia.png",alt:"Lux contempla Demacia desde un balcón al amanecer"},
  {id:"ashe-freljord",name:"Ashe",title:"Aurora de Freljord",region:"FRELJORD · ALBA",description:"Ashe contempla un horizonte helado bajo la aurora. El arco en sus manos y la calma del amanecer reflejan su deseo de reunir a los pueblos de Freljord.",file:"06-ashe-freljord.png",alt:"Ashe en una cordillera nevada bajo una aurora"},
  {id:"miss-fortune-bilgewater",name:"Miss Fortune",title:"Puerto de Bilgewater",region:"BILGEWATER · ATARDECER",description:"Miss Fortune cruza las cubiertas mojadas de Bilgewater al caer el sol. Entre barcos y reflejos dorados, la capitana parece conocer cada peligro que se oculta en el puerto.",file:"07-miss-fortune-bilgewater.png",alt:"Miss Fortune en un puerto al atardecer"},
  {id:"ekko-zaun",name:"Ekko",title:"Relojes de Zaun",region:"ZAUN · CREPÚSCULO",description:"Sobre los tejados de Zaun, Ekko observa relojes, vapor y luces industriales. Cada segundo es una oportunidad de corregir el rumbo y proteger el hogar que conoce mejor que nadie.",file:"08-ekko-zaun.png",alt:"Ekko observa Zaun desde un tejado"},
  {id:"leona-targon",name:"Leona",title:"Primer sol de Targon",region:"TARGON · AMANECER",description:"Leona recibe el primer sol sobre el monte Targon. Su armadura devuelve la luz al paisaje y transforma el amanecer en una imagen de firmeza y determinación.",file:"09-leona-targon.png",alt:"Leona en un templo de Targon al amanecer"},
  {id:"diana-targon",name:"Diana",title:"Reflejo lunar",region:"TARGON · NOCHE",description:"Diana se detiene junto a un templo reflejado en el agua. La luna ilumina un sendero discreto, reservado para quien está dispuesta a cuestionar lo que le enseñaron.",file:"10-diana-targon.png",alt:"Diana junto a un estanque bajo la luna"},
  {id:"irelia-jonia",name:"Irelia",title:"Pétalos de Jonia",region:"JONIA · PRIMAVERA",description:"Tras la lluvia, Irelia permanece en un patio de Jonia cubierto de pétalos. Sus hojas parecen suspendidas en la brisa, listas para convertir una danza en defensa de su hogar.",file:"11-irelia-jonia.png",alt:"Irelia en un patio de Jonia con pétalos"},
  {id:"kindred-bosque",name:"Kindred",title:"El bosque escucha",region:"BOSQUE · ALBA",description:"La niebla del bosque se abre ante Cordero y Lobo. Entre luciérnagas y árboles antiguos, la pareja recuerda que toda vida encuentra su final de una forma u otra.",file:"12-kindred-bosque.png",alt:"Kindred en un bosque antiguo al amanecer"},
  {id:"teemo-bandlewood",name:"Teemo",title:"Mañana en Bandlewood",region:"BANDLEWOOD · MAÑANA",description:"Teemo descansa junto a un arroyo de Bandlewood. El pequeño explorador disfruta de una mañana tranquila, aunque sus pasos siempre esconden curiosidad y alguna sorpresa preparada.",file:"13-teemo-bandlewood.png",alt:"Teemo sentado sobre un hongo en un bosque luminoso"},
  {id:"thresh-islas-sombra",name:"Thresh",title:"Bruma de las Islas",region:"ISLAS DE LA SOMBRA · NOCHE",description:"Una linterna espectral atraviesa la bruma de las Islas de la Sombra. Thresh espera entre ruinas, satisfecho con que una sola luz baste para atraer a quien debería alejarse.",file:"14-thresh-islas-sombra.png",alt:"Thresh en una calzada de las Islas de la Sombra"},
  {id:"36-cho-gath",name:"Cho'Gath",title:"Cho'Gath",region:"EL VACÍO · NOCHE",description:"Entre grietas violetas del Vacío, Cho'Gath avanza como una amenaza imposible de ignorar. Cada paso empequeñece el paisaje y convierte la noche en una advertencia.",file:"36-cho-gath.webp",alt:"Cho'Gath en un paisaje de el vacío"},
  {id:"37-corki",name:"Corki",title:"Corki",region:"PILTOVER · AMANECER",description:"Corki sobrevuela Piltover con su máquina entre torres y nubes del amanecer. El piloto yordle convierte una patrulla rutinaria en otra excusa para lanzarse a la aventura.",file:"37-corki.webp",alt:"Corki en un paisaje de piltover"},
  {id:"38-darius",name:"Darius",title:"Darius",region:"NOXUS · CREPÚSCULO",description:"En el crepúsculo de Noxus, Darius sostiene su hacha frente a una tierra conquistada. Su presencia habla de disciplina, fuerza y una lealtad inquebrantable al imperio.",file:"38-darius.webp",alt:"Darius en un paisaje de noxus"},
  {id:"39-dr-mundo",name:"Dr. Mundo",title:"Dr. Mundo",region:"ZAUN · ATARDECER",description:"Las luces químicas de Zaun iluminan la enorme silueta de Mundo. Con una sonrisa desconcertante y su maletín improvisado, recorre las calles convencido de que está ayudando.",file:"39-dr-mundo.webp",alt:"Dr. Mundo en un paisaje de zaun"},
  {id:"40-draven",name:"Draven",title:"Draven",region:"NOXUS · NOCHE",description:"Draven entra en la arena noxiana bajo un cielo nocturno. Las antorchas iluminan sus hachas giratorias y un escenario donde cada victoria necesita público.",file:"40-draven.webp",alt:"Draven en un paisaje de noxus"},
  {id:"41-elise",name:"Elise",title:"Elise",region:"NOXUS · AMANECER",description:"Elise emerge entre piedra y telarañas bajo una luz pálida. Su elegancia invita a acercarse, pero el templo guarda indicios de la criatura que acecha tras esa apariencia.",file:"41-elise.webp",alt:"Elise en un paisaje de noxus"},
  {id:"43-ezreal",name:"Ezreal",title:"Ezreal",region:"PILTOVER · ATARDECER",description:"Ezreal examina un hallazgo antiguo mientras cae la tarde sobre Piltover. Su guantelete brilla con la promesa de otro viaje que seguramente contará como una gran hazaña.",file:"43-ezreal.webp",alt:"Ezreal en un paisaje de piltover"},
  {id:"42-evelynn",name:"Evelynn",title:"Evelynn",region:"RUNATERRA · CREPÚSCULO",description:"Al caer el crepúsculo, Evelynn aparece donde la luz empieza a fallar. Su belleza disfraza una amenaza paciente, dispuesta a convertir la curiosidad de otros en su ventaja.",file:"42-evelynn.webp",alt:"Evelynn en un paisaje de runaterra"},
  {id:"47-galio",name:"Galio",title:"Galio",region:"DEMACIA · ATARDECER",description:"Galio se recorta contra el cielo de Demacia como una fortaleza viviente. La piedra de su cuerpo despierta ante la magia y ofrece a la ciudad un guardián monumental.",file:"47-galio.webp",alt:"Galio en un paisaje de demacia"},
  {id:"48-gangplank",name:"Gangplank",title:"Gangplank",region:"BILGEWATER · NOCHE",description:"Entre barcos y humo, Gangplank reclama su lugar en Bilgewater. La noche realza las cicatrices de un capitán que nunca ha confundido el poder con la misericordia.",file:"48-gangplank.webp",alt:"Gangplank en un paisaje de bilgewater"},
  {id:"49-garen",name:"Garen",title:"Garen",region:"DEMACIA · AMANECER",description:"Garen avanza ante las murallas de Demacia con la primera luz. La espada al hombro y su postura firme expresan el deber que guía al comandante de la Vanguardia Intrépida.",file:"49-garen.webp",alt:"Garen en un paisaje de demacia"},
  {id:"50-gnar",name:"Gnar",title:"Gnar",region:"FRELJORD · CREPÚSCULO",description:"Gnar descubre un rastro nuevo en la nieve de Freljord. Su pequeña figura resulta encantadora, pero el paisaje tiene espacio de sobra para la furia que puede despertar.",file:"50-gnar.webp",alt:"Gnar en un paisaje de freljord"},
  {id:"45-fiora",name:"Fiora",title:"Fiora",region:"DEMACIA · AMANECER",description:"Fiora alza su estoque en un patio demaciano al amanecer. Cada línea de la escena acompaña la concentración de una duelista para quien el honor se demuestra con precisión.",file:"45-fiora.webp",alt:"Fiora en un paisaje de demacia"},
  {id:"46-fizz",name:"Fizz",title:"Fizz",region:"BILGEWATER · CREPÚSCULO",description:"Fizz salta entre el oleaje y los muelles de Bilgewater. El travieso habitante del mar convierte el crepúsculo en un juego del que los marineros quizá prefieran mantenerse lejos.",file:"46-fizz.webp",alt:"Fizz en un paisaje de bilgewater"},
  {id:"44-fiddlesticks",name:"Fiddlesticks",title:"Fiddlesticks",region:"RUNATERRA · NOCHE",description:"Un espantapájaros inmóvil espera en el borde del camino. La noche parece escuchar con Fiddlesticks, una figura que da forma a los miedos que nadie se atreve a nombrar.",file:"44-fiddlesticks.webp",alt:"Fiddlesticks en un paisaje de runaterra"},
  {id:"51-gragas",name:"Gragas",title:"Gragas",region:"FRELJORD · ATARDECER",description:"Gragas atraviesa el frío de Freljord con un enorme barril. La luz del atardecer suaviza la nieve, aunque su búsqueda de la bebida perfecta promete acabar en alboroto.",file:"51-gragas.webp",alt:"Gragas en un paisaje de freljord"},
  {id:"55-heimerdinger",name:"Heimerdinger",title:"Heimerdinger",region:"PILTOVER · ATARDECER",description:"En un taller de Piltover, Heimerdinger revisa otra de sus invenciones. Engranajes y lámparas rodean al científico yordle, siempre dispuesto a probar una idea nueva.",file:"55-heimerdinger.webp",alt:"Heimerdinger en un paisaje de piltover"},
  {id:"56-hwei",name:"Hwei",title:"Hwei",region:"JONIA · NOCHE",description:"Hwei contempla un paisaje de Jonia después de pintar en la noche. Sus colores dejan ver una imaginación poderosa y una sensibilidad que convierte cada trazo en emoción.",file:"56-hwei.webp",alt:"Hwei en un paisaje de jonia"},
  {id:"57-illaoi",name:"Illaoi",title:"Illaoi",region:"BILGEWATER · AMANECER",description:"Illaoi recibe el amanecer frente al mar de Bilgewater. Su ídolo descansa cerca, mientras las olas recuerdan la fuerza del movimiento y la fe que ella representa.",file:"57-illaoi.webp",alt:"Illaoi en un paisaje de bilgewater"},
  {id:"58-ivern",name:"Ivern",title:"Ivern",region:"JONIA · CREPÚSCULO",description:"Ivern camina entre árboles de Jonia que parecen inclinarse a saludarlo. Su paso transforma el crepúsculo en un encuentro amable con la vida secreta del bosque.",file:"58-ivern.webp",alt:"Ivern en un paisaje de jonia"},
  {id:"59-janna",name:"Janna",title:"Janna",region:"ZAUN · ATARDECER",description:"Una corriente limpia atraviesa el aire denso de Zaun. Janna aparece como un respiro sobre los tejados, una presencia protectora para quienes siguen creyendo en la esperanza.",file:"59-janna.webp",alt:"Janna en un paisaje de zaun"},
  {id:"60-jarvan-iv",name:"Jarvan IV",title:"Jarvan IV",region:"DEMACIA · NOCHE",description:"Jarvan IV observa Demacia desde una muralla bajo la noche. Su armadura y su estandarte hablan del peso de liderar un reino que espera valor de su príncipe.",file:"60-jarvan-iv.webp",alt:"Jarvan IV en un paisaje de demacia"},
  {id:"61-jax",name:"Jax",title:"Jax",region:"RUNATERRA · AMANECER",description:"Jax se detiene junto a una ruina al amanecer, con su farol a modo de arma. Su figura sugiere siglos de combates y la espera de un desafío digno.",file:"61-jax.webp",alt:"Jax en un paisaje de runaterra"},
  {id:"62-jayce",name:"Jayce",title:"Jayce",region:"PILTOVER · CREPÚSCULO",description:"El martillo de Jayce brilla frente a las torres de Piltover. Entre laboratorio y ciudad, el inventor contempla lo que la tecnología puede construir y lo que debe proteger.",file:"62-jayce.webp",alt:"Jayce en un paisaje de piltover"},
  {id:"63-jhin",name:"Jhin",title:"Jhin",region:"JONIA · ATARDECER",description:"Jhin observa un escenario de Jonia como si ya hubiera decidido su composición. La luz del atardecer vuelve hermosa una escena cuya calma es tan calculada como inquietante.",file:"63-jhin.webp",alt:"Jhin en un paisaje de jonia"},
  {id:"64-k-sante",name:"K'Sante",title:"K'Sante",region:"SHURIMA · NOCHE",description:"K'Sante se alza ante las piedras de Shurima con sus ntofos. La noche encuentra preparado al cazador de monstruos de Nazumah para defender a los suyos.",file:"64-k-sante.webp",alt:"K'Sante en un paisaje de shurima"},
  {id:"65-kai-sa",name:"Kai'Sa",title:"Kai'Sa",region:"EL VACÍO · AMANECER",description:"Kai'Sa avanza entre formas imposibles del Vacío hacia una franja de amanecer. Su traje vivo revela años de supervivencia en un lugar que transformaría a cualquiera.",file:"65-kai-sa.webp",alt:"Kai'Sa en un paisaje de el vacío"},
  {id:"66-kalista",name:"Kalista",title:"Kalista",region:"ISLAS DE LA SOMBRA · CREPÚSCULO",description:"Kalista cruza la bruma de las Islas de la Sombra con su lanza. Cada silueta a su alrededor parece recordar una promesa rota y la venganza que aún exige.",file:"66-kalista.webp",alt:"Kalista en un paisaje de islas de la sombra"},
  {id:"52-graves",name:"Graves",title:"Graves",region:"BILGEWATER · NOCHE",description:"Graves espera en un muelle de Bilgewater, con el arma preparada y humo en el aire. La noche le ofrece otra oportunidad de salir de problemas que quizá él mismo empezó.",file:"52-graves.webp",alt:"Graves en un paisaje de bilgewater"},
  {id:"53-gwen",name:"Gwen",title:"Gwen",region:"ISLAS DE LA SOMBRA · AMANECER",description:"Gwen sostiene sus tijeras entre la niebla de las Islas de la Sombra. Sus colores y su mirada curiosa aportan una chispa de vida a un paisaje dominado por lo espectral.",file:"53-gwen.webp",alt:"Gwen en un paisaje de islas de la sombra"},
  {id:"54-hecarim",name:"Hecarim",title:"Hecarim",region:"ISLAS DE LA SOMBRA · CREPÚSCULO",description:"El galope de Hecarim rompe el silencio de las Islas de la Sombra. Su ejército espectral parece surgir de la bruma antes de que el crepúsculo termine.",file:"54-hecarim.webp",alt:"Hecarim en un paisaje de islas de la sombra"},
  {id:"67-karma",name:"Karma",title:"Karma",region:"JONIA · ATARDECER",description:"Karma contempla Jonia al caer la tarde. El paisaje sereno contrasta con las decisiones difíciles de una líder que reúne recuerdos de muchas vidas.",file:"67-karma.webp",alt:"Karma en un paisaje de jonia"},
  {id:"72-kayn",name:"Kayn",title:"Kayn",region:"JONIA · NOCHE",description:"Kayn avanza por Jonia con una guadaña que parece tener voluntad propia. La noche hace visible la tensión entre el asesino y el poder oscuro que intenta dominar.",file:"72-kayn.webp",alt:"Kayn en un paisaje de jonia"},
  {id:"73-kennen",name:"Kennen",title:"Kennen",region:"JONIA · AMANECER",description:"Kennen cruza un puente de Jonia cuando aparece el sol. La energía eléctrica a su alrededor anticipa la velocidad con la que este pequeño guardián puede intervenir.",file:"73-kennen.webp",alt:"Kennen en un paisaje de jonia"},
  {id:"74-kha-zix",name:"Kha'Zix",title:"Kha'Zix",region:"EL VACÍO · CREPÚSCULO",description:"Kha'Zix acecha entre grietas del Vacío mientras se apaga la luz. Su cuerpo cambiante está hecho para perseguir, aprender y volver cada encuentro más peligroso.",file:"74-kha-zix.webp",alt:"Kha'Zix en un paisaje de el vacío"},
  {id:"75-kled",name:"Kled",title:"Kled",region:"NOXUS · ATARDECER",description:"Kled irrumpe en el paisaje de Noxus montado en Skaarl. Su valentía desmedida y su mal humor convierten cualquier camino del atardecer en territorio que reclama como suyo.",file:"75-kled.webp",alt:"Kled en un paisaje de noxus"},
  {id:"76-kog-maw",name:"Kog'Maw",title:"Kog'Maw",region:"EL VACÍO · NOCHE",description:"Kog'Maw observa el mundo desde una abertura del Vacío. Su curiosidad casi infantil es engañosa: el suelo alrededor muestra lo destructivo que puede resultar su apetito.",file:"76-kog-maw.webp",alt:"Kog'Maw en un paisaje de el vacío"},
  {id:"77-leblanc",name:"LeBlanc",title:"LeBlanc",region:"NOXUS · AMANECER",description:"LeBlanc aparece entre sombras noxianas cuando nace el día. Nadie sabe si la figura que ve es la verdadera; ese misterio es parte de su poder.",file:"77-leblanc.webp",alt:"LeBlanc en un paisaje de noxus"},
  {id:"78-lee-sin",name:"Lee Sin",title:"Lee Sin",region:"JONIA · CREPÚSCULO",description:"Lee Sin entrena junto a un templo de Jonia al atardecer. Sus movimientos medidos dejan sentir una disciplina forjada para percibir más allá de lo que alcanzan los ojos.",file:"78-lee-sin.webp",alt:"Lee Sin en un paisaje de jonia"},
  {id:"79-lillia",name:"Lillia",title:"Lillia",region:"JONIA · ATARDECER",description:"Lillia asoma entre flores y árboles de Jonia cuando cambia la luz. Tímida pero curiosa, sigue los sueños que flotan por el bosque como pequeñas luces.",file:"79-lillia.webp",alt:"Lillia en un paisaje de jonia"},
  {id:"80-lissandra",name:"Lissandra",title:"Lissandra",region:"FRELJORD · NOCHE",description:"Lissandra se alza entre torres de hielo en Freljord. La noche y la escarcha ocultan planes antiguos que la Bruja de Hielo ha guardado durante generaciones.",file:"80-lissandra.webp",alt:"Lissandra en un paisaje de freljord"},
  {id:"81-locke",name:"Locke",title:"Locke",region:"RUNATERRA · AMANECER",description:"Locke se prepara ante un paisaje todavía cubierto por la niebla del amanecer. Sus lentes violetas y su equipo de exorcista sugieren un oficio dedicado a enfrentar amenazas que otros no ven.",file:"81-locke.webp",alt:"Locke en un paisaje de runaterra"},
  {id:"82-lucian",name:"Lucian",title:"Lucian",region:"RUNATERRA · CREPÚSCULO",description:"Lucian atraviesa la penumbra con sus dos pistolas de luz. El crepúsculo marca la frontera entre el mundo de los vivos y las sombras que ha jurado combatir.",file:"82-lucian.webp",alt:"Lucian en un paisaje de runaterra"},
  {id:"68-karthus",name:"Karthus",title:"Karthus",region:"ISLAS DE LA SOMBRA · NOCHE",description:"La voz de Karthus parece elevarse desde las ruinas de las Islas de la Sombra. Bajo la noche, su canto convierte la bruma en una ceremonia tan solemne como aterradora.",file:"68-karthus.webp",alt:"Karthus en un paisaje de islas de la sombra"},
  {id:"69-kassadin",name:"Kassadin",title:"Kassadin",region:"EL VACÍO · AMANECER",description:"Kassadin emerge de una grieta del Vacío antes del amanecer. Su armadura cuenta una lucha prolongada contra aquello que amenaza con devorar la realidad.",file:"69-kassadin.webp",alt:"Kassadin en un paisaje de el vacío"},
  {id:"70-katarina",name:"Katarina",title:"Katarina",region:"NOXUS · CREPÚSCULO",description:"Katarina cruza los tejados de Noxus al crepúsculo. Sus hojas brillan apenas un instante, suficiente para recordar por qué es una de sus asesinas más temidas.",file:"70-katarina.webp",alt:"Katarina en un paisaje de noxus"},
  {id:"71-kayle",name:"Kayle",title:"Kayle",region:"DEMACIA · ATARDECER",description:"Kayle desciende sobre Demacia envuelta en una luz severa. La espada y sus alas ofrecen una imagen majestuosa de justicia, incluso cuando esa justicia deja poco espacio para la duda.",file:"71-kayle.webp",alt:"Kayle en un paisaje de demacia"},
  {id:"83-lulu",name:"Lulu",title:"Lulu",region:"BANDLE CITY · ATARDECER",description:"Lulu sigue a Pix por un sendero de Bandle City. El atardecer adquiere colores imposibles allí donde la yordle deja que su imaginación altere el mundo.",file:"83-lulu.webp",alt:"Lulu en un paisaje de bandle city"},
  {id:"87-maokai",name:"Maokai",title:"Maokai",region:"ISLAS DE LA SOMBRA · ATARDECER",description:"Maokai se abre paso por un bosque corrompido de las Islas de la Sombra. Bajo su corteza persiste la voluntad de devolver vida a una tierra cubierta de bruma.",file:"87-maokai.webp",alt:"Maokai en un paisaje de islas de la sombra"},
  {id:"88-mel",name:"Mel",title:"Mel",region:"RUNATERRA · NOCHE",description:"Mel contempla el horizonte con la compostura de quien conoce la política y el poder. Los reflejos dorados de la noche insinúan la fuerza que ha aprendido a proteger.",file:"88-mel.webp",alt:"Mel en un paisaje de runaterra"},
  {id:"89-milio",name:"Milio",title:"Milio",region:"IXTAL · AMANECER",description:"Milio camina entre la vegetación de Ixtal con pequeñas llamas amistosas. El amanecer acompaña a un joven que usa el fuego para cuidar y sanar.",file:"89-milio.webp",alt:"Milio en un paisaje de ixtal"},
  {id:"90-mordekaiser",name:"Mordekaiser",title:"Mordekaiser",region:"RUNATERRA · CREPÚSCULO",description:"Mordekaiser emerge entre metal y oscuridad, empequeñeciendo las ruinas a su alrededor. El crepúsculo apenas suaviza la presencia de un conquistador que se niega a permanecer muerto.",file:"90-mordekaiser.webp",alt:"Mordekaiser en un paisaje de runaterra"},
  {id:"91-morgana",name:"Morgana",title:"Morgana",region:"DEMACIA · ATARDECER",description:"Morgana se aparta de la luz de Demacia y abre sus alas oscuras. Su magia ofrece compasión a quienes fueron juzgados antes de poder contar su historia.",file:"91-morgana.webp",alt:"Morgana en un paisaje de demacia"},
  {id:"92-naafiri",name:"Naafiri",title:"Naafiri",region:"SHURIMA · NOCHE",description:"La manada de Naafiri se mueve entre dunas shurimanas bajo la noche. Sus ojos brillan al unísono, como una sola voluntad extendida entre muchos cuerpos.",file:"92-naafiri.webp",alt:"Naafiri en un paisaje de shurima"},
  {id:"93-nami",name:"Nami",title:"Nami",region:"RUNATERRA · AMANECER",description:"Nami surge de aguas luminosas con su báculo en la mano. El amanecer revela la urgencia de su viaje para proteger a su pueblo bajo el mar.",file:"93-nami.webp",alt:"Nami en un paisaje de runaterra"},
  {id:"94-nasus",name:"Nasus",title:"Nasus",region:"SHURIMA · CREPÚSCULO",description:"Nasus contempla las ruinas de Shurima mientras cae la luz. Entre columnas y arena, el erudito ascendido carga con la memoria de un imperio perdido.",file:"94-nasus.webp",alt:"Nasus en un paisaje de shurima"},
  {id:"95-nautilus",name:"Nautilus",title:"Nautilus",region:"BILGEWATER · ATARDECER",description:"Nautilus se alza entre restos de barcos en el puerto de Bilgewater. Su enorme traje emerge del agua como un recordatorio de las deudas que el mar no olvida.",file:"95-nautilus.webp",alt:"Nautilus en un paisaje de bilgewater"},
  {id:"96-neeko",name:"Neeko",title:"Neeko",region:"IXTAL · NOCHE",description:"Neeko aparece entre plantas de Ixtal, con colores que cambian bajo la noche. Su curiosidad por los demás vuelve el paisaje tan vivo como su propia apariencia.",file:"96-neeko.webp",alt:"Neeko en un paisaje de ixtal"},
  {id:"97-nidalee",name:"Nidalee",title:"Nidalee",region:"IXTAL · AMANECER",description:"Nidalee observa la selva de Ixtal antes de que el sol alcance el suelo. La cazadora conoce cada sonido de ese territorio y se mueve entre lo humano y lo salvaje.",file:"97-nidalee.webp",alt:"Nidalee en un paisaje de ixtal"},
  {id:"98-nilah",name:"Nilah",title:"Nilah",region:"BILGEWATER · CREPÚSCULO",description:"Nilah avanza con una sonrisa hacia un peligro que otros evitarían. El agua de Bilgewater refleja su espada y la alegría sobrenatural que acompaña cada una de sus hazañas.",file:"98-nilah.webp",alt:"Nilah en un paisaje de bilgewater"},
  {id:"84-maestro-yi",name:"Maestro Yi",title:"Maestro Yi",region:"JONIA · NOCHE",description:"Maestro Yi medita bajo la noche de Jonia con la espada a su lado. La quietud de la escena expresa el equilibrio entre una técnica veloz y una mente paciente.",file:"84-maestro-yi.webp",alt:"Maestro Yi en un paisaje de jonia"},
  {id:"85-malphite",name:"Malphite",title:"Malphite",region:"IXTAL · AMANECER",description:"Malphite se confunde con los riscos de Ixtal hasta que la montaña parece moverse. La primera luz revela el tamaño de este guardián de piedra.",file:"85-malphite.webp",alt:"Malphite en un paisaje de ixtal"},
  {id:"86-malzahar",name:"Malzahar",title:"Malzahar",region:"EL VACÍO · CREPÚSCULO",description:"Malzahar extiende la mano ante una abertura del Vacío. El crepúsculo tiñe el suelo mientras la promesa de un destino inevitable atrae a sus seguidores.",file:"86-malzahar.webp",alt:"Malzahar en un paisaje de el vacío"},
  {id:"99-nocturne",name:"Nocturne",title:"Nocturne",region:"RUNATERRA · ATARDECER",description:"La sombra de Nocturne invade el paisaje antes de que termine el día. Donde aparece, hasta el atardecer parece incapaz de apartar el miedo de los sueños.",file:"99-nocturne.webp",alt:"Nocturne en un paisaje de runaterra"},
  {id:"103-ornn",name:"Ornn",title:"Ornn",region:"FRELJORD · ATARDECER",description:"Ornn trabaja junto a una fragua encendida en Freljord. Entre nieve y chispas, el viejo artesano da forma al metal sin pedir espectadores para su obra.",file:"103-ornn.webp",alt:"Ornn en un paisaje de freljord"},
  {id:"104-pantheon",name:"Pantheon",title:"Pantheon",region:"TARGON · NOCHE",description:"Pantheon asciende por Targon bajo un cielo estrellado. Cada paso del guerrero mortal recuerda que la voluntad humana puede desafiar incluso a los dioses.",file:"104-pantheon.webp",alt:"Pantheon en un paisaje de targon"},
  {id:"105-poppy",name:"Poppy",title:"Poppy",region:"DEMACIA · AMANECER",description:"Poppy sostiene su martillo frente a una muralla demaciana al amanecer. Busca a un héroe legendario sin advertir cuánto valor lleva ella misma en el camino.",file:"105-poppy.webp",alt:"Poppy en un paisaje de demacia"},
  {id:"106-pyke",name:"Pyke",title:"Pyke",region:"BILGEWATER · CREPÚSCULO",description:"Pyke emerge entre las aguas oscuras de Bilgewater con una lista de nombres. El crepúsculo sobre el puerto parece contener la respiración cuando comienza su cacería.",file:"106-pyke.webp",alt:"Pyke en un paisaje de bilgewater"},
  {id:"107-qiyana",name:"Qiyana",title:"Qiyana",region:"IXTAL · ATARDECER",description:"Qiyana posa ante la selva de Ixtal con su arma circular. El oro del atardecer acompaña a una heredera convencida de que su poder merece un trono.",file:"107-qiyana.webp",alt:"Qiyana en un paisaje de ixtal"},
  {id:"108-quinn",name:"Quinn",title:"Quinn",region:"DEMACIA · NOCHE",description:"Quinn vigila Demacia desde lo alto mientras Valor explora el cielo nocturno. Su vínculo permite descubrir peligros mucho antes de que alcancen la frontera.",file:"108-quinn.webp",alt:"Quinn en un paisaje de demacia"},
  {id:"109-rakan",name:"Rakan",title:"Rakan",region:"JONIA · AMANECER",description:"Rakan entra en un claro de Jonia con la ligereza de una celebración. Plumas y luz del amanecer acompañan a un vastaya que siempre deja una impresión imposible de olvidar.",file:"109-rakan.webp",alt:"Rakan en un paisaje de jonia"},
  {id:"110-rammus",name:"Rammus",title:"Rammus",region:"SHURIMA · CREPÚSCULO",description:"Rammus rueda entre piedras antiguas de Shurima y se detiene sin prisa. Su expresión indescifrable deja a los viajeros preguntándose si acaban de conocer una leyenda.",file:"110-rammus.webp",alt:"Rammus en un paisaje de shurima"},
  {id:"111-rek-sai",name:"Rek'Sai",title:"Rek'Sai",region:"EL VACÍO · ATARDECER",description:"Bajo la arena marcada por grietas del Vacío, Rek'Sai detecta el menor movimiento. El paisaje parece vacío hasta que la cazadora decide salir a la superficie.",file:"111-rek-sai.webp",alt:"Rek'Sai en un paisaje de el vacío"},
  {id:"112-rell",name:"Rell",title:"Rell",region:"NOXUS · NOCHE",description:"Rell avanza por Noxus sobre metal arrancado a sus enemigos. La noche rodea a una joven que convirtió el dolor en una fuerza capaz de romper cadenas.",file:"112-rell.webp",alt:"Rell en un paisaje de noxus"},
  {id:"113-renata-glasc",name:"Renata Glasc",title:"Renata Glasc",region:"ZAUN · AMANECER",description:"Renata Glasc observa Zaun desde una oficina elevada. Frascos y luces químicas recuerdan que su influencia puede sentirse incluso donde ella nunca pone un pie.",file:"113-renata-glasc.webp",alt:"Renata Glasc en un paisaje de zaun"},
  {id:"114-renekton",name:"Renekton",title:"Renekton",region:"SHURIMA · CREPÚSCULO",description:"Renekton surge entre ruinas shurimanas con su hoja alzada. La luz del crepúsculo resalta la furia de un guerrero ascendido consumido por el pasado.",file:"114-renekton.webp",alt:"Renekton en un paisaje de shurima"},
  {id:"100-nunu-y-willump",name:"Nunu y Willump",title:"Nunu y Willump",region:"FRELJORD · NOCHE",description:"Nunu y Willump cruzan la nieve de Freljord bajo las estrellas. Para el niño y su amigo, cada montaña es parte de una aventura que pueden inventar juntos.",file:"100-nunu-y-willump.webp",alt:"Nunu y Willump en un paisaje de freljord"},
  {id:"101-olaf",name:"Olaf",title:"Olaf",region:"FRELJORD · AMANECER",description:"Olaf se enfrenta al viento helado de Freljord con las hachas preparadas. Busca una batalla memorable, seguro de que el frío no será quien lo detenga.",file:"101-olaf.webp",alt:"Olaf en un paisaje de freljord"},
  {id:"102-orianna",name:"Orianna",title:"Orianna",region:"PILTOVER · CREPÚSCULO",description:"Orianna camina por Piltover con su esfera flotando a su lado. Los reflejos del crepúsculo en su cuerpo mecánico dan a la escena una delicadeza inesperada.",file:"102-orianna.webp",alt:"Orianna en un paisaje de piltover"},
  {id:"115-rengar",name:"Rengar",title:"Rengar",region:"IXTAL · ATARDECER",description:"Rengar aguarda entre las hojas de Ixtal, atento a cada rastro. El atardecer se convierte en un tablero de caza para quien mide su vida por desafíos cada vez mayores.",file:"115-rengar.webp",alt:"Rengar en un paisaje de ixtal"},
  {id:"119-samira",name:"Samira",title:"Samira",region:"NOXUS · ATARDECER",description:"Samira cruza una calle noxiana como si ya estuviera en medio de una acrobacia. El atardecer ilumina sus armas y su gusto por el peligro espectacular.",file:"119-samira.webp",alt:"Samira en un paisaje de noxus"},
  {id:"120-sejuani",name:"Sejuani",title:"Sejuani",region:"FRELJORD · NOCHE",description:"Sejuani guía a los suyos a través de una noche helada de Freljord. Sobre Bristle, mira el camino con la dureza de quien lucha para que su tribu sobreviva.",file:"120-sejuani.webp",alt:"Sejuani en un paisaje de freljord"},
  {id:"121-senna",name:"Senna",title:"Senna",region:"ISLAS DE LA SOMBRA · AMANECER",description:"Senna sostiene su enorme arma frente a la bruma de las Islas de la Sombra. El amanecer llega con ella, una luz tenaz nacida de todo lo que logró resistir.",file:"121-senna.webp",alt:"Senna en un paisaje de islas de la sombra"},
  {id:"122-seraphine",name:"Seraphine",title:"Seraphine",region:"PILTOVER · CREPÚSCULO",description:"Seraphine escucha el pulso de Piltover entre luces del crepúsculo. Su escenario busca reunir voces distintas y convertir el ruido de la ciudad en una canción compartida.",file:"122-seraphine.webp",alt:"Seraphine en un paisaje de piltover"},
  {id:"123-sett",name:"Sett",title:"Sett",region:"JONIA · ATARDECER",description:"Sett observa una arena de Jonia antes de entrar. La luz cálida del atardecer marca los golpes de una vida que lo llevó de luchador a dueño del espectáculo.",file:"123-sett.webp",alt:"Sett en un paisaje de jonia"},
  {id:"124-shaco",name:"Shaco",title:"Shaco",region:"RUNATERRA · NOCHE",description:"Shaco aparece al borde de una sonrisa imposible en un escenario nocturno. Sus juguetes y sombras transforman el camino en una broma que nadie quiere recibir.",file:"124-shaco.webp",alt:"Shaco en un paisaje de runaterra"},
  {id:"126-shyvana",name:"Shyvana",title:"Shyvana",region:"DEMACIA · CREPÚSCULO",description:"Shyvana protege el horizonte de Demacia mientras el cielo se oscurece. Bajo su figura humana late un poder dracónico que puede cambiar la escena en un instante.",file:"126-shyvana.webp",alt:"Shyvana en un paisaje de demacia"},
  {id:"127-singed",name:"Singed",title:"Singed",region:"ZAUN · ATARDECER",description:"Singed trabaja entre recipientes de Zaun bañados por una luz enfermiza. El atardecer fuera del laboratorio contrasta con experimentos que nunca parecen conocer límites.",file:"127-singed.webp",alt:"Singed en un paisaje de zaun"},
  {id:"125-shen",name:"Shen",title:"Shen",region:"JONIA · AMANECER",description:"Shen cruza un templo de Jonia cuando aparece la primera luz. Su deber consiste en conservar el equilibrio entre el mundo visible y el espiritual, incluso cuando exige sacrificios.",file:"125-shen.webp",alt:"Shen en un paisaje de jonia"},
  {id:"128-sion",name:"Sion",title:"Sion",region:"NOXUS · NOCHE",description:"Sion avanza bajo los estandartes de Noxus durante la noche. Su cuerpo enorme y marcado por la guerra recuerda un pasado que el imperio se niega a dejar descansar.",file:"128-sion.webp",alt:"Sion en un paisaje de noxus"},
  {id:"129-sivir",name:"Sivir",title:"Sivir",region:"SHURIMA · AMANECER",description:"Sivir examina una tumba de Shurima al amanecer con su arma circular preparada. Entre tesoros y arena, la mercenaria confía más en su experiencia que en las leyendas.",file:"129-sivir.webp",alt:"Sivir en un paisaje de shurima"},
  {id:"130-skarner",name:"Skarner",title:"Skarner",region:"IXTAL · CREPÚSCULO",description:"Skarner se alza entre la piedra y la selva de Ixtal. El crepúsculo resalta su tamaño y la voluntad con que protege un mundo que teme ver alterado.",file:"130-skarner.webp",alt:"Skarner en un paisaje de ixtal"},
  {id:"117-rumble",name:"Rumble",title:"Rumble",region:"BANDLE CITY · AMANECER",description:"Rumble pone en marcha su robot entre las casas de Bandle City. Chispas y humo del amanecer acompañan al inventor que convierte piezas sueltas en algo formidable.",file:"117-rumble.webp",alt:"Rumble en un paisaje de bandle city"},
  {id:"116-riven",name:"Riven",title:"Riven",region:"NOXUS · NOCHE",description:"Riven sostiene una espada rota ante un paisaje noxiano en silencio. La noche da espacio a los recuerdos de una soldado que busca decidir quién quiere ser ahora.",file:"116-riven.webp",alt:"Riven en un paisaje de noxus"},
  {id:"118-ryze",name:"Ryze",title:"Ryze",region:"RUNATERRA · CREPÚSCULO",description:"Ryze estudia un símbolo antiguo al caer la tarde. Ha recorrido Runaterra durante años para impedir que un poder demasiado grande vuelva a caer en manos equivocadas.",file:"118-ryze.webp",alt:"Ryze en un paisaje de runaterra"},
  {id:"131-smolder",name:"Smolder",title:"Smolder",region:"RUNATERRA · ATARDECER",description:"Smolder contempla el mundo desde una altura que pronto le quedará pequeña. El cielo del atardecer acompaña a un joven dragón orgulloso, curioso y todavía lejos de dominar sus llamas.",file:"131-smolder.webp",alt:"Smolder en un paisaje de runaterra"},
  {id:"135-sylas",name:"Sylas",title:"Sylas",region:"DEMACIA · ATARDECER",description:"Sylas rompe la quietud de Demacia con cadenas que ya no lo mantienen preso. El atardecer enciende su magia y la convicción de que el reino debe cambiar.",file:"135-sylas.webp",alt:"Sylas en un paisaje de demacia"},
  {id:"136-syndra",name:"Syndra",title:"Syndra",region:"JONIA · NOCHE",description:"Syndra flota sobre Jonia rodeada de energía oscura. La noche deja espacio a un poder que fue contenido durante demasiado tiempo y ya no pide permiso.",file:"136-syndra.webp",alt:"Syndra en un paisaje de jonia"},
  {id:"137-tahm-kench",name:"Tahm Kench",title:"Tahm Kench",region:"BILGEWATER · AMANECER",description:"Tahm Kench aparece junto al agua de Bilgewater con una sonrisa impecable. La claridad del amanecer no hace más seguros los tratos que ofrece.",file:"137-tahm-kench.webp",alt:"Tahm Kench en un paisaje de bilgewater"},
  {id:"138-taliyah",name:"Taliyah",title:"Taliyah",region:"SHURIMA · CREPÚSCULO",description:"Taliyah desliza piedras bajo sus pies a través del desierto shurimano. El crepúsculo revela a una joven capaz de convertir la tierra en un camino hacia su hogar.",file:"138-taliyah.webp",alt:"Taliyah en un paisaje de shurima"},
  {id:"139-talon",name:"Talon",title:"Talon",region:"NOXUS · ATARDECER",description:"Talon cruza las alturas de Noxus con las cuchillas ocultas. La luz del atardecer encuentra la ciudad, pero apenas alcanza al asesino que se mueve entre sus sombras.",file:"139-talon.webp",alt:"Talon en un paisaje de noxus"},
  {id:"140-taric",name:"Taric",title:"Taric",region:"TARGON · NOCHE",description:"Taric permanece en la ladera de Targon bajo las estrellas. Gemas y armadura recogen la luz de una montaña donde aprendió a proteger todo aquello que considera hermoso.",file:"140-taric.webp",alt:"Taric en un paisaje de targon"},
  {id:"141-tristana",name:"Tristana",title:"Tristana",region:"BANDLE CITY · AMANECER",description:"Tristana avanza por Bandle City con su enorme cañón al hombro. El amanecer promete una nueva expedición para la yordle que nunca se queda esperando aventuras.",file:"141-tristana.webp",alt:"Tristana en un paisaje de bandle city"},
  {id:"142-trundle",name:"Trundle",title:"Trundle",region:"FRELJORD · CREPÚSCULO",description:"Trundle se impone entre rocas heladas de Freljord con su garrote. El crepúsculo dibuja a un rey troll astuto, siempre dispuesto a aprovechar la fuerza de otros.",file:"142-trundle.webp",alt:"Trundle en un paisaje de freljord"},
  {id:"143-tryndamere",name:"Tryndamere",title:"Tryndamere",region:"FRELJORD · ATARDECER",description:"Tryndamere atraviesa la nieve de Freljord con su gran espada. La luz del atardecer marca las cicatrices de un guerrero cuya furia lo mantiene luchando.",file:"143-tryndamere.webp",alt:"Tryndamere en un paisaje de freljord"},
  {id:"144-twisted-fate",name:"Twisted Fate",title:"Twisted Fate",region:"BILGEWATER · NOCHE",description:"Twisted Fate baraja cartas en una calle húmeda de Bilgewater. La noche brilla sobre su sombrero mientras decide qué juego puede llevarlo a la próxima fortuna.",file:"144-twisted-fate.webp",alt:"Twisted Fate en un paisaje de bilgewater"},
  {id:"145-twitch",name:"Twitch",title:"Twitch",region:"ZAUN · AMANECER",description:"Twitch surge de una alcantarilla de Zaun al amanecer. Entre tuberías y residuos, el tirador rata parece encantado de encontrar nuevos blancos para su ballesta.",file:"145-twitch.webp",alt:"Twitch en un paisaje de zaun"},
  {id:"146-udyr",name:"Udyr",title:"Udyr",region:"FRELJORD · CREPÚSCULO",description:"Udyr escucha a los espíritus de Freljord entre el viento de la montaña. El crepúsculo dibuja la fuerza salvaje que lleva dentro y el esfuerzo por mantenerla en equilibrio.",file:"146-udyr.webp",alt:"Udyr en un paisaje de freljord"},
  {id:"132-sona",name:"Sona",title:"Sona",region:"DEMACIA · NOCHE",description:"Sona toca su instrumento frente a una Demacia nocturna. Las notas parecen llenar el aire con emociones que la música puede expresar mejor que las palabras.",file:"132-sona.webp",alt:"Sona en un paisaje de demacia"},
  {id:"133-soraka",name:"Soraka",title:"Soraka",region:"TARGON · AMANECER",description:"Soraka recibe el amanecer en las alturas de Targon. Su luz suave y su báculo ofrecen consuelo a quienes encuentra en un mundo que nunca deja de necesitar cuidado.",file:"133-soraka.webp",alt:"Soraka en un paisaje de targon"},
  {id:"134-swain",name:"Swain",title:"Swain",region:"NOXUS · CREPÚSCULO",description:"Swain observa Noxus desde una altura mientras los cuervos cruzan el cielo. El crepúsculo acompaña a un estratega que ve en cada sombra una pieza del futuro.",file:"134-swain.webp",alt:"Swain en un paisaje de noxus"},
  {id:"147-urgot",name:"Urgot",title:"Urgot",region:"ZAUN · ATARDECER",description:"Urgot avanza entre las chimeneas de Zaun con el metal de su cuerpo brillando. Su presencia convierte el atardecer industrial en una prueba de resistencia.",file:"147-urgot.webp",alt:"Urgot en un paisaje de zaun"},
  {id:"150-veigar",name:"Veigar",title:"Veigar",region:"BANDLE CITY · CREPÚSCULO",description:"Veigar prepara un hechizo bajo el cielo de Bandle City. Su empeño por parecer temible resulta tan grande como los destellos mágicos que iluminan el crepúsculo.",file:"150-veigar.webp",alt:"Veigar en un paisaje de bandle city"},
  {id:"151-vel-koz",name:"Vel'Koz",title:"Vel'Koz",region:"EL VACÍO · ATARDECER",description:"El ojo de Vel'Koz examina un paisaje abierto por el Vacío. La luz del atardecer cae sobre ruinas que para esta criatura son, ante todo, cosas por comprender.",file:"151-vel-koz.webp",alt:"Vel'Koz en un paisaje de el vacío"},
  {id:"152-vex",name:"Vex",title:"Vex",region:"ISLAS DE LA SOMBRA · NOCHE",description:"Vex permanece entre la bruma de las Islas de la Sombra con su sombra a un lado. La noche combina perfectamente con su humor, aunque incluso ella atrae historias inesperadas.",file:"152-vex.webp",alt:"Vex en un paisaje de islas de la sombra"},
  {id:"153-vi",name:"Vi",title:"Vi",region:"PILTOVER · AMANECER",description:"Vi recorre Piltover con los guanteletes listos mientras nace el día. Las calles prometen problemas y ella parece dispuesta a resolverlos de la forma más directa.",file:"153-vi.webp",alt:"Vi en un paisaje de piltover"},
  {id:"154-viego",name:"Viego",title:"Viego",region:"ISLAS DE LA SOMBRA · CREPÚSCULO",description:"Viego atraviesa la bruma de las Islas de la Sombra con la espada baja. El crepúsculo mantiene viva la obsesión que arrastró a un reino entero hacia la ruina.",file:"154-viego.webp",alt:"Viego en un paisaje de islas de la sombra"},
  {id:"155-viktor",name:"Viktor",title:"Viktor",region:"ZAUN · ATARDECER",description:"Viktor observa Zaun entre máquinas y destellos de energía. Su visión de un futuro mejor aparece en cada pieza metálica, aunque otros cuestionen el precio del cambio.",file:"155-viktor.webp",alt:"Viktor en un paisaje de zaun"},
  {id:"157-volibear",name:"Volibear",title:"Volibear",region:"FRELJORD · AMANECER",description:"Volibear domina una cordillera de Freljord cuando irrumpe el amanecer. La tormenta que lo rodea recuerda una fuerza antigua, anterior a las ciudades y sus leyes.",file:"157-volibear.webp",alt:"Volibear en un paisaje de freljord"},
  {id:"156-vladimir",name:"Vladimir",title:"Vladimir",region:"NOXUS · NOCHE",description:"Vladimir se mueve por un salón noxiano iluminado apenas por la noche. Su elegancia oculta siglos de secretos y un dominio inquietante de la sangre.",file:"156-vladimir.webp",alt:"Vladimir en un paisaje de noxus"},
  {id:"158-warwick",name:"Warwick",title:"Warwick",region:"ZAUN · CREPÚSCULO",description:"Warwick sigue un rastro por las calles húmedas de Zaun. Al caer la luz, su silueta mezcla furia y un pasado humano que aún se resiste a desaparecer.",file:"158-warwick.webp",alt:"Warwick en un paisaje de zaun"},
  {id:"159-wukong",name:"Wukong",title:"Wukong",region:"JONIA · ATARDECER",description:"Wukong se detiene sobre una roca de Jonia con su bastón en mano. El atardecer encuentra a un luchador ingenioso, siempre dispuesto a aprender de otro desafío.",file:"159-wukong.webp",alt:"Wukong en un paisaje de jonia"},
  {id:"160-xayah",name:"Xayah",title:"Xayah",region:"JONIA · NOCHE",description:"Xayah permanece entre árboles de Jonia con plumas afiladas preparadas. La noche ofrece cobertura a una rebelde que lucha para recuperar el hogar de los vastaya.",file:"160-xayah.webp",alt:"Xayah en un paisaje de jonia"},
  {id:"161-xerath",name:"Xerath",title:"Xerath",region:"SHURIMA · AMANECER",description:"Xerath ilumina las ruinas de Shurima con energía arcana. El amanecer apenas compite con el fulgor de un poder liberado de su prisión.",file:"161-xerath.webp",alt:"Xerath en un paisaje de shurima"},
  {id:"162-xin-zhao",name:"Xin Zhao",title:"Xin Zhao",region:"DEMACIA · CREPÚSCULO",description:"Xin Zhao monta guardia ante Demacia al caer el crepúsculo. Su lanza y su mirada firme muestran la lealtad de quien eligió proteger un nuevo hogar.",file:"162-xin-zhao.webp",alt:"Xin Zhao en un paisaje de demacia"},
  {id:"148-varus",name:"Varus",title:"Varus",region:"JONIA · NOCHE",description:"Varus tensa su arco en la oscuridad de Jonia. El arma concentra una energía antigua y peligrosa que vuelve incierta la voluntad de quien la sostiene.",file:"148-varus.webp",alt:"Varus en un paisaje de jonia"},
  {id:"149-vayne",name:"Vayne",title:"Vayne",region:"DEMACIA · AMANECER",description:"Vayne busca una señal entre las sombras de Demacia cuando llega el amanecer. La luz revela apenas su ballesta y la determinación de una cazadora de monstruos.",file:"149-vayne.webp",alt:"Vayne en un paisaje de demacia"},
  {id:"163-yone",name:"Yone",title:"Yone",region:"JONIA · ATARDECER",description:"Yone avanza por Jonia con dos espadas mientras cae el sol. Una hoja pertenece al mundo de los vivos; la otra recuerda los espíritus que sigue persiguiendo.",file:"163-yone.webp",alt:"Yone en un paisaje de jonia"},
  {id:"167-zaahen",name:"Zaahen",title:"Zaahen",region:"RUNATERRA · ATARDECER",description:"Zaahen aparece ante un horizonte de Runaterra con su arma oscura. La luz del atardecer recorta su forma imponente y sugiere una historia marcada por la guerra y poderes antiguos.",file:"167-zaahen.webp",alt:"Zaahen en un paisaje de runaterra"},
  {id:"168-zac",name:"Zac",title:"Zac",region:"ZAUN · NOCHE",description:"Zac rebota entre tuberías de Zaun bajo la noche. Su forma cambiante puede asustar a primera vista, pero la ciudad ha encontrado en él a un protector inesperado.",file:"168-zac.webp",alt:"Zac en un paisaje de zaun"},
  {id:"169-zed",name:"Zed",title:"Zed",region:"JONIA · AMANECER",description:"Zed se desliza entre sombras de Jonia antes de que salga el sol. Su armadura y sus hojas revelan a un maestro dispuesto a usar métodos que otros rechazan.",file:"169-zed.webp",alt:"Zed en un paisaje de jonia"},
  {id:"170-zeri",name:"Zeri",title:"Zeri",region:"ZAUN · CREPÚSCULO",description:"Zeri corre por una calle de Zaun entre cables y destellos. El crepúsculo parece encenderse a su paso, impulsado por la energía con que protege a su comunidad.",file:"170-zeri.webp",alt:"Zeri en un paisaje de zaun"},
  {id:"171-ziggs",name:"Ziggs",title:"Ziggs",region:"RUNATERRA · ATARDECER",description:"Ziggs observa el resultado de otra explosión con evidente satisfacción. Bajo el cielo anaranjado, la nube de humo convierte su entusiasmo por los inventos en un espectáculo.",file:"171-ziggs.webp",alt:"Ziggs en un paisaje de runaterra"},
  {id:"172-zilean",name:"Zilean",title:"Zilean",region:"SHURIMA · NOCHE",description:"Zilean contempla las ruinas de Shurima mientras la noche avanza. A su alrededor, el tiempo parece detenerse el instante suficiente para recordar una ciudad perdida.",file:"172-zilean.webp",alt:"Zilean en un paisaje de shurima"},
  {id:"173-zoe",name:"Zoe",title:"Zoe",region:"TARGON · AMANECER",description:"Zoe atraviesa el cielo de Targon entre colores imposibles al amanecer. Para el aspecto del Crepúsculo, las estrellas y los portales son parte de un juego sin límites.",file:"173-zoe.webp",alt:"Zoe en un paisaje de targon"},
  {id:"164-yorick",name:"Yorick",title:"Yorick",region:"ISLAS DE LA SOMBRA · NOCHE",description:"Yorick camina por las Islas de la Sombra acompañado de espíritus. La noche cubre una misión solitaria: liberar a su tierra de la bruma que la consume.",file:"164-yorick.webp",alt:"Yorick en un paisaje de islas de la sombra"},
  {id:"165-yunara",name:"Yunara",title:"Yunara",region:"JONIA · AMANECER",description:"Yunara permanece entre templos de Jonia mientras nace el día. La energía espiritual que la rodea une disciplina y una fuerza antigua, lista para defender el equilibrio de su hogar.",file:"165-yunara.webp",alt:"Yunara en un paisaje de jonia"},
  {id:"166-yuumi",name:"Yuumi",title:"Yuumi",region:"BANDLE CITY · CREPÚSCULO",description:"Yuumi viaja sobre su libro mágico por un Bandle City lleno de color. El crepúsculo trae nuevos lugares que explorar y quizá alguna pista para reencontrar a su amiga.",file:"166-yuumi.webp",alt:"Yuumi en un paisaje de bandle city"},
  {id:"174-zyra",name:"Zyra",title:"Zyra",region:"IXTAL · CREPÚSCULO",description:"Zyra emerge entre enredaderas de Ixtal bajo la luz del crepúsculo. Las flores a su alrededor son tan hermosas como peligrosas y responden a una voluntad salvaje.",file:"174-zyra.webp",alt:"Zyra en un paisaje de ixtal"}
];
